"""Labeling functions for agent progress probe.

Each LF takes a sliding window of steps and returns:
  1 = progress, 0 = stagnation, -1 = abstain
"""

from __future__ import annotations

import re
from difflib import SequenceMatcher
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from data_loader import Step, Trajectory

PROGRESS = 1
STAGNATION = 0
ABSTAIN = -1

EDIT_PATTERN = re.compile(r"^edit\s+\d+", re.MULTILINE)
SEARCH_CMDS = {"search_dir", "search_file", "find_file", "find", "grep"}


def _extract_edited_files(steps: list[Step]) -> tuple[int, set[str]]:
    """Count edit commands and unique files edited in a window."""
    edit_count = 0
    files = set()
    for step in steps:
        if not step.is_action:
            continue
        cmd = step.command
        if not cmd:
            continue
        if cmd.strip().startswith("edit"):
            edit_count += 1
            # Try to get the filename from the next observation
            idx = step.index
            for s in steps:
                if s.index == idx + 1 and s.is_observation:
                    match = re.search(r"\[File:\s*([^\]]+?)(?:\s*\(\d+\s*lines)", s.text)
                    if match:
                        files.add(match.group(1).strip())
                    break
    return edit_count, files


def _count_search_only(steps: list[Step]) -> int:
    """Count consecutive search/find commands without any edit."""
    count = 0
    for step in steps:
        if not step.is_action:
            continue
        cmd = step.command
        if not cmd:
            continue
        first_word = cmd.strip().split()[0] if cmd.strip() else ""
        if first_word in SEARCH_CMDS:
            count += 1
    return count


def lf_file_diff_delta(window: list[Step], trajectory: Trajectory, window_position: dict) -> int:
    """LF1: Whether the agent is meaningfully modifying code in this window."""
    edit_count, files = _extract_edited_files(window)

    if edit_count >= 2 and len(files) >= 1:
        return PROGRESS
    if edit_count == 0:
        search_count = _count_search_only(window)
        if search_count >= 3:
            return STAGNATION
        return ABSTAIN
    return ABSTAIN


def _cmd_similarity(a: str, b: str) -> float:
    """Character-level similarity between two commands using SequenceMatcher."""
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    return SequenceMatcher(None, a, b).ratio()


def _has_consecutive_similar(commands: list[str], min_run: int = 3, threshold: float = 0.9) -> bool:
    """Check if there are ≥min_run consecutive commands with similarity > threshold."""
    if len(commands) < min_run:
        return False
    run = 1
    for i in range(1, len(commands)):
        if _cmd_similarity(commands[i - 1], commands[i]) >= threshold:
            run += 1
            if run >= min_run:
                return True
        else:
            run = 1
    return False


def lf_command_repetition(window: list[Step], trajectory: Trajectory, window_position: dict) -> int:
    """LF2: Detect command repetition patterns as stagnation signal."""
    commands = [s.command for s in window if s.is_action and s.command is not None]

    if len(commands) < 2:
        return ABSTAIN

    if _has_consecutive_similar(commands, min_run=3, threshold=1.0):
        return STAGNATION

    if _has_consecutive_similar(commands, min_run=3, threshold=0.9):
        return STAGNATION

    if len(set(commands)) == len(commands):
        return PROGRESS

    return ABSTAIN


# --- Deprecated ---
def _parse_test_pass_rate(text: str) -> float | None:
    passed = 0
    failed = 0
    passed_lines = re.findall(r"PASSED\s+\S+", text)
    failed_lines = re.findall(r"FAILED\s+\S+", text)
    passed += len(passed_lines)
    failed += len(failed_lines)
    summary_passed = re.search(r"(\d+)\s+passed", text)
    summary_failed = re.search(r"(\d+)\s+failed", text)
    if summary_passed and passed == 0:
        passed = int(summary_passed.group(1))
    if summary_failed and failed == 0:
        failed = int(summary_failed.group(1))
    total = passed + failed
    if total == 0:
        return None
    return passed / total


def lf_test_pass_rate_transition_deprecated(window: list[Step], trajectory: Trajectory, window_position: dict) -> int:
    """LF2 (deprecated): Whether test pass rate is improving within the window."""
    test_runs = []
    for step in window:
        if not step.is_observation:
            continue
        if not step.has_test_output:
            continue
        rate = _parse_test_pass_rate(step.text)
        if rate is not None:
            test_runs.append(rate)
    if len(test_runs) < 2:
        return ABSTAIN
    last = test_runs[-1]
    second_last = test_runs[-2]
    if last > second_last:
        return PROGRESS
    return STAGNATION


def lf_outcome_backpropagation(window: list[Step], trajectory: Trajectory, window_position: dict) -> int:
    """LF3: Label last windows based on final trajectory outcome."""
    total_windows = window_position["total_windows"]
    window_idx = window_position["window_idx"]

    is_last_two = window_idx >= total_windows - 2

    if trajectory.exit_status in ("exit_context",):
        return STAGNATION

    if not is_last_two:
        return ABSTAIN

    if trajectory.target:
        return PROGRESS
    else:
        return STAGNATION


ALL_LFS = [
    ("file_diff_delta", lf_file_diff_delta),
    ("command_repetition", lf_command_repetition),
    ("outcome_backpropagation", lf_outcome_backpropagation),
]

# SWE-agent trajectories data loader for agent_progress_probe project.
# Loads and parses nebius/SWE-agent-trajectories JSONL data into structured objects.

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional


@dataclass
class Step:
    """A single step in an agent trajectory."""
    index: int
    role: str  # "system", "user", or "ai"
    text: str
    mask: bool
    cutoff_date: Optional[str] = None
    system_prompt: Optional[str] = None

    @property
    def is_action(self) -> bool:
        return self.role == "ai"

    @property
    def is_observation(self) -> bool:
        return self.role == "user" and self.index > 0

    @property
    def is_system(self) -> bool:
        return self.role == "system"

    @property
    def command(self) -> Optional[str]:
        """Extract the command from an AI step's code block. Returns None for non-AI steps."""
        if self.role != "ai":
            return None
        match = re.search(r"```\n?(.*?)```", self.text, re.DOTALL)
        if match:
            return match.group(1).strip()
        return None

    @property
    def has_file_display(self) -> bool:
        return "[File:" in self.text

    @property
    def has_error(self) -> bool:
        return "Traceback" in self.text or "Error" in self.text

    @property
    def has_test_output(self) -> bool:
        text = self.text
        return ("PASSED" in text or "FAILED" in text) and "test" in text.lower()


@dataclass
class TestResult:
    """Parsed test results from eval_logs."""
    passed: list[str] = field(default_factory=list)
    failed: list[str] = field(default_factory=list)
    errored: list[str] = field(default_factory=list)

    @property
    def total(self) -> int:
        return len(self.passed) + len(self.failed) + len(self.errored)

    @property
    def pass_rate(self) -> float:
        if self.total == 0:
            return 0.0
        return len(self.passed) / self.total


@dataclass
class Trajectory:
    """A complete agent trajectory for one SWE-bench instance attempt."""
    instance_id: str
    model_name: str
    target: bool  # True = resolved, False = unresolved
    steps: list[Step]
    exit_status: str
    generated_patch: Optional[str]
    eval_logs: Optional[str]

    @property
    def num_steps(self) -> int:
        return len(self.steps)

    @property
    def actions(self) -> list[Step]:
        return [s for s in self.steps if s.is_action]

    @property
    def observations(self) -> list[Step]:
        return [s for s in self.steps if s.is_observation]

    @property
    def issue_text(self) -> Optional[str]:
        """The issue description from step 1 (first user message)."""
        if len(self.steps) > 1 and self.steps[1].role == "user":
            return self.steps[1].text
        return None

    @property
    def has_patch(self) -> bool:
        return bool(self.generated_patch and self.generated_patch.strip())

    def parse_eval_test_results(self) -> Optional[TestResult]:
        """Parse test results from eval_logs.

        Returns:
            TestResult with lists of passed/failed/errored test names,
            or None if eval_logs is empty or has no test section.
        """
        if not self.eval_logs:
            return None
        start_marker = "___TESTS_SECTION___"
        end_marker = "___TESTS_SECTION_END"
        if start_marker not in self.eval_logs:
            return None
        start = self.eval_logs.index(start_marker)
        end = self.eval_logs.index(end_marker) if end_marker in self.eval_logs else len(self.eval_logs)
        section = self.eval_logs[start:end]

        result = TestResult()
        for line in section.splitlines():
            line = line.strip()
            if line.startswith("PASSED "):
                result.passed.append(line[7:])
            elif line.startswith("FAILED "):
                name = line[7:].split(" - ")[0]
                result.failed.append(name)
            elif line.startswith("ERROR "):
                result.errored.append(line[6:])
        return result

    def extract_mid_trajectory_test_results(self) -> list[tuple[int, TestResult]]:
        """Find pytest runs within the trajectory observations.

        Returns:
            List of (step_index, TestResult) for steps containing pytest output.
        """
        results = []
        for step in self.observations:
            if not step.has_test_output:
                continue
            tr = TestResult()
            for line in step.text.splitlines():
                line = line.strip()
                if line.startswith("PASSED "):
                    tr.passed.append(line[7:])
                elif line.startswith("FAILED "):
                    name = line[7:].split(" - ")[0]
                    tr.failed.append(name)
                elif line.startswith("ERROR "):
                    tr.errored.append(line[6:])
            summary = re.search(r"(\d+) passed", step.text)
            if summary and not tr.passed:
                tr.passed = [f"unnamed_{i}" for i in range(int(summary.group(1)))]
            summary = re.search(r"(\d+) failed", step.text)
            if summary and not tr.failed:
                tr.failed = [f"unnamed_{i}" for i in range(int(summary.group(1)))]
            if tr.total > 0:
                results.append((step.index, tr))
        return results

    def get_edit_commands(self) -> list[tuple[int, str]]:
        """Extract all edit commands from the trajectory.

        Returns:
            List of (step_index, command_text) for steps containing edit commands.
        """
        edits = []
        for step in self.actions:
            cmd = step.command
            if cmd and cmd.strip().startswith("edit"):
                edits.append((step.index, cmd))
        return edits


def parse_trajectory(raw: dict) -> Trajectory:
    """Parse a single raw record dict into a Trajectory object.

    Args:
        raw: A dict with keys: instance_id, model_name, target, trajectory,
             exit_status, generated_patch, eval_logs.

    Returns:
        A Trajectory object with parsed Steps.
    """
    steps = []
    for i, step_raw in enumerate(raw.get("trajectory") or []):
        steps.append(Step(
            index=i,
            role=step_raw.get("role", "unknown"),
            text=step_raw.get("text") or "",
            mask=step_raw.get("mask", False),
            cutoff_date=step_raw.get("cutoff_date"),
            system_prompt=step_raw.get("system_prompt"),
        ))

    return Trajectory(
        instance_id=raw.get("instance_id", ""),
        model_name=raw.get("model_name", ""),
        target=raw.get("target", False),
        steps=steps,
        exit_status=raw.get("exit_status", ""),
        generated_patch=raw.get("generated_patch"),
        eval_logs=raw.get("eval_logs"),
    )


def extract_steps(trajectory: Trajectory) -> list[Step]:
    """Extract the step sequence from a trajectory, excluding the system step.

    Args:
        trajectory: A parsed Trajectory object.

    Returns:
        List of Steps starting from step 1 (the issue description),
        excluding the system prompt step.
    """
    return [s for s in trajectory.steps if not s.is_system]


def load_trajectories(path: str | Path) -> list[Trajectory]:
    """Load trajectories from a JSONL file.

    Args:
        path: Path to a .jsonl file where each line is a JSON record.

    Returns:
        List of Trajectory objects.
    """
    path = Path(path)
    trajectories = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            raw = json.loads(line)
            trajectories.append(parse_trajectory(raw))
    return trajectories


def load_trajectories_streaming(path: str | Path, limit: int | None = None):
    """Lazily yield trajectories from a JSONL file.

    Args:
        path: Path to a .jsonl file.
        limit: Maximum number of trajectories to yield. None for all.

    Yields:
        Trajectory objects one at a time.
    """
    path = Path(path)
    count = 0
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            raw = json.loads(line)
            yield parse_trajectory(raw)
            count += 1
            if limit and count >= limit:
                break


